class Component extends DCLogic {
  constructor(props) { super(props); this.state = { active: 0 }; }
  renderVals() {
    const P = [
      ['Aster House', 'Hospitality — Identity, Digital', '2026', '/_blob/42b22810c00e2f735db015ffafe54d8e'],
      ['Nocturne', 'Culture — Art Direction', '2026', '/_blob/386a1268d05ea963158718bf4e98bdd9'],
      ['Forma', 'Architecture — Digital', '2025', '/_blob/b42423a16f028a31bd54a92269f3d22f'],
      ['Arc Athletics', 'Sport — Identity', '2025', '/_blob/8a63c05d2914aa8e034fc2e49a9fc138'],
      ['Halden', 'Landscape — Editorial', '2025', '/_blob/07404ef1f1a5cb5cc893d07cca9c479c'],
      ['Field Notes', 'Publishing — Digital', '2024', '/_blob/0b6d3602385510faba9329337df8a3b6'],
      ['Sola Ceramics', 'Craft — Identity', '2024', '/_blob/659cb95cfb70c2f3580a72fa7e8e86bc'],
      ['Kiln', 'Food — Identity', '2024', '/_blob/20dfede26066f6aa5c9ab20538cd5514'],
      ['Meridian', 'Property — Digital', '2023', '/_blob/a3437c78eb58d2c8153dd1accd4695da'],
      ['Open Room', 'Exhibition — Art Direction', '2023', '/_blob/39b0a9f9c025cf05ca660b6010b06846']
    ];
    const a = this.state.active;
    const items = P.map((p, i) => ({
      n: String(i + 1).padStart(2, '0'), name: p[0], disc: p[1], year: p[2],
      href: ['Project', 'ProjectNocturne', 'ProjectForma', 'ProjectArc', 'ProjectHalden', 'ProjectFieldNotes', 'ProjectSola', 'ProjectKiln', 'ProjectMeridian', 'ProjectOpenRoom'][i] + '.dc.html',
      cls: 'idx-row' + (i === a ? ' on' : ''),
      pick: () => { if (this.state.active !== i) this.setState({ active: i }); }
    }));
