class Component extends DCLogic {
  constructor(props) { super(props); this.state = { filter: 'All', view: 'list', hover: -1 }; }
  renderVals() {
    const P = [
      ['Aster House', 'Hospitality', ['Identity', 'Digital'], '2026', '/_blob/42b22810c00e2f735db015ffafe54d8e'],
      ['Nocturne', 'Culture', ['Art Direction'], '2026', '/_blob/386a1268d05ea963158718bf4e98bdd9'],
      ['Forma', 'Architecture', ['Digital'], '2025', '/_blob/b42423a16f028a31bd54a92269f3d22f'],
      ['Arc Athletics', 'Sport', ['Identity'], '2025', '/_blob/8a63c05d2914aa8e034fc2e49a9fc138'],
      ['Halden', 'Landscape', ['Editorial'], '2025', '/_blob/07404ef1f1a5cb5cc893d07cca9c479c'],
      ['Field Notes', 'Publishing', ['Editorial', 'Digital'], '2024', '/_blob/0b6d3602385510faba9329337df8a3b6'],
      ['Sola Ceramics', 'Craft', ['Identity', 'Art Direction'], '2024', '/_blob/659cb95cfb70c2f3580a72fa7e8e86bc'],
      ['Kiln', 'Food & Drink', ['Identity'], '2024', '/_blob/20dfede26066f6aa5c9ab20538cd5514'],
      ['Meridian', 'Property', ['Digital'], '2023', '/_blob/a3437c78eb58d2c8153dd1accd4695da'],
      ['Open Room', 'Exhibition', ['Art Direction', 'Editorial'], '2023', '/_blob/39b0a9f9c025cf05ca660b6010b06846']
    ];
    const H = ['Project', 'ProjectNocturne', 'ProjectForma', 'ProjectArc', 'ProjectHalden', 'ProjectFieldNotes', 'ProjectSola', 'ProjectKiln', 'ProjectMeridian', 'ProjectOpenRoom'];
    const all = P.map((p, i) => ({ i, href: H[i] + '.dc.html', n: String(i + 1).padStart(2, '0'), name: p[0], sector: p[1], tags: p[2], disc: p[2].join(', '), year: p[3], img: p[4] }));
    const F = ['All', 'Identity', 'Digital', 'Art Direction', 'Editorial'];
    const { filter, view, hover } = this.state;
    const filters = F.map((f) => {
      const on = f === filter;
      return { label: f, n: f === 'All' ? all.length : all.filter((p) => p.tags.includes(f)).length, pressed: on ? 'true' : 'false', ucls: on ? 'u on' : 'u', pick: () => this.setState({ filter: f, hover: -1 }) };
    });
    const list = filter === 'All' ? all : all.filter((p) => p.tags.includes(filter));
    const cells = ['grid-column: span 4', 'grid-column: span 5; margin-top: 120px', 'grid-column: span 3', 'grid-column: span 3; margin-top: 64px', 'grid-column: 5 / span 4', 'grid-column: span 4; margin-top: 160px'];
    const ratios = ['aspect-ratio: 4 / 5', 'aspect-ratio: 3 / 2', 'aspect-ratio: 3 / 4', 'aspect-ratio: 1 / 1', 'aspect-ratio: 4 / 5', 'aspect-ratio: 3 / 4'];
    const shown = list.map((p, k) => ({ ...p,
      rowCls: 'row' + (p.i === hover ? ' on' : ''),
      hover: () => { if (this.state.hover !== p.i) this.setState({ hover: p.i }); },
      cell: cells[k % 6], ratio: ratios[k % 6] }));
    const cur = hover >= 0 ? all[hover] : list[0] || all[0];
    return {
      filters, shown, cur, count: String(list.length).padStart(2, '0'),
      listCls: 'list' + (hover >= 0 ? ' hov' : ''),
      clear: () => this.setState({ hover: -1 }),
      isList: view === 'list', isGrid: view === 'grid',
      listOn: view === 'list' ? 'true' : 'false', gridOn: view === 'grid' ? 'true' : 'false',
      setList: () => this.setState({ view: 'list' }), setGrid: () => this.setState({ view: 'grid' })
    };
  }
}

