class Component extends DCLogic {
  constructor(props) { super(props); this.state = { g: 0 }; }
  renderVals() {
    const S = [
      ['/_blob/5fce6513f40397a517d7d80a457c2b6b', 'Room 7, the Garden Room', 'width: 56vw'],
      ['/_blob/dd4c07c2a9b46cd1371dfc9e2fa5511d', 'Pre-arrival email on a phone', 'width: 34vw'],
      ['/_blob/89e77a78ae7b7fa4eeea47d642aa3d14', 'Breakfast card', 'width: 34vw'],
      ['/_blob/0cc14b30d942d3d23ff48ef363c290be', 'Booking page', 'width: 56vw'],
      ['/_blob/f98cc9ac473e200ef615754fcb451cb7', 'Key fob, room 7', 'width: 34vw'],
      ['/_blob/63879887f2974ec6edc2b9c2b14adf4c', 'Letterhead and bill', 'width: 42vw']
    ];
    const g = this.state.g;
    const W = [56, 34, 34, 56, 34, 42];
    const off = W.slice(0, g).reduce((a, b) => a + b, 0);
    return {
      slides: S.map((s) => ({ img: s[0], alt: s[1], w: s[2] })),
      gnum: String(g + 1).padStart(2, '0'),
      trackStyle: 'transform: translateX(calc(-' + off + 'vw - ' + g + ' * var(--gap)))',
      atStart: g === 0, atEnd: g === S.length - 1,
      prev: () => this.setState({ g: Math.max(0, g - 1) }),
      next: () => this.setState({ g: Math.min(S.length - 1, g + 1) })
    };
  }
}

