      ['/_blob/ee34e25ce791434753fdc14c3e850678', 'Courtyard looking up', 34],
      ['/_blob/aa9e8b8214b2e9c4341f4c805afaadae', 'Ground floor plan', 56],
      ['/_blob/b42423a16f028a31bd54a92269f3d22f', 'Brise-soleil', 34]
    ];
