  constructor(props) { super(props); this.state = { filter: 'All' }; }
  renderVals() {
    const P = [
      ['Aster House', 'Hospitality', ['Identity', 'Digital'], '2026', '/_blob/42b22810c00e2f735db015ffafe54d8e'],
      ['Nocturne', 'Culture', ['Art Direction'], '2026', '/_blob/386a1268d05ea963158718bf4e98bdd9'],
      ['Forma', 'Architecture', ['Digital'], '2025', '/_blob/b42423a16f028a31bd54a92269f3d22f'],
      ['Arc Athletics', 'Sport', ['Identity'], '2025', '/_blob/8a63c05d2914aa8e034fc2e49a9fc138'],
      ['Halden', 'Landscape', ['Editorial'], '2025', '/_blob/07404ef1f1a5cb5cc893d07cca9c479c'],
      ['Field Notes', 'Publishing', ['Editorial', 'Digital'], '2024', '/_blob/0b6d3602385510faba9329337df8a3b6'],
      ['Sola Ceramics', 'Craft', ['Identity', 'Art Direction'], '2024', '/_blob/659cb95cfb70c2f3580a72fa7e8e86bc'],
      ['Kiln', 'Food & Drink', ['Identity'], '2024', '/_blob/20dfede26066f6aa5c9ab20538cd5514'],
      ['Meridian', 'Property', ['Digital'], '2023', '/_blob/a3437c78eb58d2c8153dd1accd4695da'],
      ['Open Room', 'Exhibition', ['Art Direction', 'Editorial'], '2023', '/_blob/39b0a9f9c025cf05ca660b6010b06846']
    ];
    const H = ['MobileProject', 'MobileProjectNocturne', 'MobileProjectForma', 'MobileProjectArc', 'MobileProjectHalden', 'MobileProjectFieldNotes', 'MobileProjectSola', 'MobileProjectKiln', 'MobileProjectMeridian', 'MobileProjectOpenRoom'];
    const all = P.map((p, i) => ({ href: H[i] + '.dc.html', n: String(i + 1).padStart(2, '0'), name: p[0], sector: p[1], tags: p[2], disc: p[2].join(', '), year: p[3], img: p[4] }));
    const F = ['All', 'Identity', 'Digital', 'Art Direction', 'Editorial'];
    const f0 = this.state.filter;
    const filters = F.map((f) => ({ label: f, n: f === 'All' ? all.length : all.filter((p) => p.tags.includes(f)).length, pressed: f === f0 ? 'true' : 'false', pick: () => this.setState({ filter: f }) }));
    const shown = f0 === 'All' ? all : all.filter((p) => p.tags.includes(f0));
    return { filters, shown, count: String(shown.length).padStart(2, '0') };
  }
}

sourceCSS:
body{margin:0;background:#F1EFEA}
.mb{--bg:#F1EFEA;--ink:#151513;--grey:#6B6862;--rule:#D6D3CC;--accent:#D4512A;--m:16px;background:var(--bg);color:var(--ink);font-family:'Geist',ui-sans-serif,system-ui,sans-serif;font-size:16px;line-height:1.5;-webkit-font-smoothing:antialiased}
.mb *{box-sizing:border-box}
.mb a{color:inherit;text-decoration:none}
.mb img{display:block;width:100%;height:100%;object-fit:cover}
.mb h1,.mb h2,.mb p,.mb ul,.mb ol{margin:0;padding:0}
.mb ul,.mb ol{list-style:none}
.mb button{font:inherit;color:inherit;background:none;border:0;padding:0;cursor:pointer}
.mb :focus-visible{outline:1px solid currentColor;outline-offset:3px}
.mono{font-family:'Geist Mono',ui-monospace,monospace;font-size:10.5px;line-height:1.45;letter-spacing:.02em;text-transform:uppercase}
.grey{color:var(--grey)}
.bar{position:sticky;top:0;z-index:5;height:56px;display:flex;align-items:center;justify-content:space-between;padding-inline:var(--m);color:#fff;mix-blend-mode:difference}
.tap{min-height:44px;display:inline-flex;align-items:center}
.chips{display:flex;gap:22px;overflow-x:auto;padding-inline:var(--m);scrollbar-width:none;border-bottom:1px solid var(--rule)}
.flt{flex:none;min-height:48px;display:inline-flex;align-items:center;gap:3px;color:var(--grey);font-size:15px}
.flt[aria-pressed="true"]{color:var(--ink);box-shadow:inset 0 -1px 0 var(--ink)}
.flt sup{font-family:'Geist Mono',monospace;font-size:9px;align-self:flex-start;margin-top:13px}
.row{display:grid;grid-template-columns:64px 1fr auto;gap:14px;align-items:center;padding-block:12px;border-bottom:1px solid var(--rule)}
.th{height:80px;overflow:hidden;background:#E4E1DA}

